/* ============================================================
   EXPRESSIVE SINGING — MAIN JS
   ============================================================ */

// ---- LANGUAGE ----
// French pages live at the site root, English pages in /en/ (generated by
// tools/build.py). The language button (#langBtn) is a plain link to the other
// version, so the current language is simply the page's <html lang>.
const currentLang = document.documentElement.lang === 'en' ? 'en' : 'fr';

// ---- NAVIGATION SCROLL ----
function initNav() {
  const nav = document.getElementById('mainNav');
  if (!nav) return;

  const onScroll = () => {
    if (window.scrollY > 40) {
      nav.classList.add('scrolled');
    } else {
      nav.classList.remove('scrolled');
    }
  };
  window.addEventListener('scroll', onScroll, { passive: true });
  onScroll();
}

// ---- HAMBURGER MENU ----
function initHamburger() {
  const toggle = document.getElementById('navToggle');
  const links = document.getElementById('navLinks');
  const nav = document.getElementById('mainNav');
  if (!toggle || !links) return;

  function closeMenu() {
    links.classList.remove('open');
    toggle.classList.remove('open');
    toggle.setAttribute('aria-expanded', 'false');
  }

  toggle.addEventListener('click', (e) => {
    e.stopPropagation();
    const isOpen = links.classList.toggle('open');
    toggle.classList.toggle('open', isOpen);
    toggle.setAttribute('aria-expanded', String(isOpen));
  });

  // Close on link click
  links.querySelectorAll('.nav-link').forEach(link => {
    link.addEventListener('click', closeMenu);
  });

  // Close when clicking outside the nav
  document.addEventListener('click', (e) => {
    if (nav && !nav.contains(e.target)) closeMenu();
  });
}

// ---- SCROLL FADE-IN ----
function initFadeIn() {
  const items = document.querySelectorAll('.fade-in');
  if (!items.length) return;

  // Fallback: ensure everything becomes visible after 400ms regardless
  setTimeout(() => {
    items.forEach(el => el.classList.add('visible'));
  }, 400);

  if (!('IntersectionObserver' in window)) {
    items.forEach(el => el.classList.add('visible'));
    return;
  }

  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('visible');
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.05, rootMargin: '0px 0px -40px 0px' });

  items.forEach(el => observer.observe(el));
}

// ---- ACTIVE NAV LINK ----
function initActiveNav() {
  const path = window.location.pathname.split('/').pop() || 'index.html';
  document.querySelectorAll('.nav-link').forEach(link => {
    const href = link.getAttribute('href');
    if (href === path || (path === '' && href === 'index.html')) {
      link.style.borderBottomWidth = '1px';
      link.style.borderBottomStyle = 'solid';
      link.style.borderBottomColor = 'var(--gold)';
      link.style.paddingBottom = '3px';
      link.style.color = 'var(--gold)';
    }
  });
}

// ---- CONTACT FORM ----
function initContactForm() {
  const form = document.getElementById('contactForm');
  if (!form) return;

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    const btn = form.querySelector('[type="submit"]');
    const original = btn.textContent;
    btn.textContent = currentLang === 'fr' ? 'Envoyé ✓' : 'Sent ✓';
    btn.style.background = 'var(--forest)';
    btn.disabled = true;
    setTimeout(() => {
      btn.textContent = original;
      btn.style.background = '';
      btn.disabled = false;
      form.reset();
    }, 3000);
  });
}

// ---- INIT ALL ----
document.addEventListener('DOMContentLoaded', () => {
  initNav();
  initHamburger();
  initFadeIn();
  initActiveNav();
  initContactForm();
});
